const $=id=>document.getElementById(id),escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0);
const KEY='itulah-ga-prototype-v2';let db;try{db=JSON.parse(localStorage.getItem(KEY))||clone(SEED)}catch{db=clone(SEED)}
let moduleName='Contracts',tabName='Sewa',role='GA',draft=null,detailTab='Form',isNew=false,attachmentBusy=false;
const byId=id=>Model.byId(db,id),nameOf=id=>byId(id)?.name||id||'—';
function persist(){try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch{$('form-error').textContent='Penyimpanan browser penuh. Kurangi lampiran; perubahan masih ada di sesi ini.';return false}}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4000)}
function badge(status){return `<span class="badge ${/DRAFT|WAITING|HOLD|RETURN|UNVERIFIED|sebagian|Dilaporkan|Baru/.test(status)?'warn':''}">${escapeHTML(status||'—')}</span>`}
function allowedKinds(){return MENUS[moduleName][tabName]}
function listRecords(){return db.filter(r=>{if(!allowedKinds().includes(r.kind))return false;if(moduleName==='Contracts')return r.group===tabName;if(moduleName==='Assets')return r.group===tabName;if(moduleName==='Fleet'){if(tabName==='Vehicles')return r.assetClass==='Kendaraan';if(tabName==='Service')return byId(r.asset)?.assetClass==='Kendaraan';}if(moduleName==='Workplace'&&tabName==='Utilities'&&r.kind==='contract')return r.group==='Langganan';if(moduleName==='Finance'&&tabName==='Inbox')return ['SUBMITTED','RETURNED','HOLD','WAITING_INVOICE'].includes(r.status);return true})}
function go(m,t){moduleName=m;tabName=t||Object.keys(MENUS[m])[0];$('search').value='';render()}
function render(){
$('nav').innerHTML=Object.keys(MENUS).filter(m=>m!=='Finance').map(m=>`<button data-menu="${m}" class="${m===moduleName?'active':''}">${m}<span>↗</span></button>`).join('');$('crumb').textContent=`Workspace / ${moduleName} / ${tabName}`;$('title').textContent=moduleName;$('description').textContent=DESCRIPTIONS[moduleName];$('tabs').innerHTML=Object.keys(MENUS[moduleName]).map(t=>`<button data-tab="${t}" class="${t===tabName?'active':''}">${t}</button>`).join('');let rows=listRecords();let attention=rows.filter(r=>r.end&&r.end>=TODAY&&r.end<='2026-11-23'||['SUBMITTED','WAITING_INVOICE','Dilaporkan','Baru','HOLD','RETURNED'].includes(r.status)).length;
$('stats').innerHTML=`<div class="stat"><small>${escapeHTML(tabName)}</small><strong>${rows.length}</strong><small>Record pada tampilan ini</small></div><div class="stat"><small>Perlu diperhatikan</small><strong>${attention}</strong><small>Antrean terbuka / berakhir dalam 60 hari dari 24 Sep</small></div><div class="stat"><small>Simulasi peran aktif</small><strong>${role}</strong><small>${role==='GA'?'Kelola operasi · ajukan invoice':'Review klasifikasi · posting · pembayaran'}</small></div>`;
$('list-title').textContent=tabName;$('list-hint').textContent='Buka record untuk form lengkap, dokumen, relasi, dan riwayat.';
$('guidance').innerHTML=moduleName==='Finance'?'Draft → Diajukan → Review Finance → Posting AP → Pembayaran. Recurring hanya membuat draft; nominal perkiraan tidak menjadi tagihan aktual otomatis.':moduleName==='Fleet'?'Vehicles adalah register aset yang sama. Service membaca Maintenance. Dokumen, pemakaian, dan BBM menunjuk kendaraan tersebut.':moduleName==='Workplace'?'Utilities membaca kontrak Langganan + log meter. Supplies dan checklist adalah fakta operasi sendiri; pengadaan, stok, dan pembayaran tetap mengikuti domain pemiliknya.':'GA mengelola fakta operasional. Tombol “Ajukan invoice” mengisi satu draft Finance, dengan referensi dan dokumen sumber. Angka biaya aktual dibaca dari baris bill POSTED.';renderRows()}
function renderRows(){let q=$('search').value.toLowerCase(),site=$('site-filter').value;let rows=listRecords().filter(r=>(!site||r.site===site)&&(r.name+' '+r.id+' '+nameOf(r.vendor)).toLowerCase().includes(q));$('rows').innerHTML=rows.length?rows.map(r=>`<tr><td><button class="link" data-open="${r.id}">${escapeHTML(r.name)}</button><small>${r.id} · ${SCHEMAS[r.kind].label}</small></td><td>${escapeHTML(r.site||'Shared supplier')}<small>${escapeHTML(nameOf(r.asset||r.vendor||r.contract))}</small></td><td>${badge(r.status)}</td><td>${r.kind==='bill'?money(Model.gross(r)):r.kind==='template'?`${r.mode} · ${escapeHTML(r.frequency)}`:r.kind==='reading'?`${r.current-r.previous} ${r.unit}`:r.end?escapeHTML(r.end):r.kind==='asset'?escapeHTML(r.holder||'Belum ditetapkan'):r.next?escapeHTML(r.next):'—'}</td><td><button class="link" data-open="${r.id}" aria-label="Buka ${r.id}">↗</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">Belum ada record. Buat baru atau ubah filter pencarian.</td></tr>'}
function locked(){return draft?.kind==='bill'&&draft.status==='POSTED'||draft?.kind==='template'&&role!=='Finance'}
function visibleField(f){
if(draft.kind==='contract'){
 if(f.key==='counterparty')return draft.group==='Disewakan';
 if(f.key==='vendor')return draft.group!=='Disewakan';
 if(['customer'].includes(f.key))return ['Langganan','Asuransi','Izin'].includes(draft.group);
 if(['capacity','meter'].includes(f.key))return draft.group==='Langganan';
 if(f.key==='sla')return draft.group==='Jasa';
 if(f.key==='coverage')return draft.group==='Asuransi';
 if(f.key==='issuer')return ['Asuransi','Izin'].includes(draft.group);
}
if(draft.kind==='asset'){
 if(['plate','vin','engine','fuelType','odometer','year'].includes(f.key))return draft.assetClass==='Kendaraan';
 if(['seats','licenseEnd'].includes(f.key))return draft.group==='Software';
 if(['milestone','progress'].includes(f.key))return draft.group==='Projects';
}
if(draft.kind==='document'&&f.key==='end'&&draft.contract)return false;
return true;
}
function fieldHTML(f){let v=draft[f.key]??'',disabled=f.readonly||locked()||draft.kind==='bill'&&role==='GA'&&['withholding','review','reviewNote'].includes(f.key);let attrs=`id="field-${f.key}" name="${f.key}" ${disabled?'disabled':''} ${f.required?'required':''}`;let input;if(f.type==='account'){input=`<select ${attrs}><option value="">Tidak ada usulan</option>${VENDOR_ACCOUNTS.map(a=>`<option value="${a}" ${v===a?'selected':''}>${a}</option>`).join('')}</select>`}else if(f.type==='select'||f.type==='ref'){let opts=f.type==='ref'?db.filter(r=>r.kind===f.kind&&(f.key!=='asset'||!['trip','fuel','document'].includes(draft.kind)||r.assetClass==='Kendaraan')).map(r=>[r.id,r.name+' · '+r.id]):f.values.map(x=>[x,x]);input=`<select ${attrs}><option value="">Pilih…</option>${opts.map(([key,label])=>`<option value="${escapeHTML(key)}" ${v===key?'selected':''}>${escapeHTML(label)}</option>`).join('')}</select>`}else if(f.type==='textarea')input=`<textarea ${attrs}>${escapeHTML(v)}</textarea>`;else input=`<input ${attrs} type="${f.type}" ${f.type==='number'?'min="0" step="any"':''} value="${escapeHTML(v)}">`;return `<div class="field ${f.type==='textarea'?'wide':''}"><label for="field-${f.key}">${f.label}${f.required?' <em>*</em>':''}${f.readonly?' · hanya baca':''}</label>${input}</div>`}
function capture(){if(!draft)return;if(detailTab==='Form'){for(const s of SCHEMAS[draft.kind].sections)for(const f of s.fields){let field=$('field-'+f.key);if(field&&!field.disabled)draft[f.key]=f.type==='number'?(field.value===''?'':Number(field.value)):field.value.trim()}if(draft.kind==='bill'){document.querySelectorAll('[data-line-key]').forEach(el=>{if(!el.disabled){const l=draft.lines[Number(el.dataset.index)];l[el.dataset.lineKey]=el.dataset.lineKey==='prepaid'?el.checked:el.dataset.lineKey==='amount'?(el.value===''?'':Number(el.value)):el.value}})}}}
function openRecord(id){draft=clone(byId(id));isNew=false;detailTab='Form';showEditor()}
function create(kind,defaults={}){draft=seedRecord(kind,Model.nextId(db,kind),'',{site:$('site-filter').value||'C007',status:'Draft'});for(const s of SCHEMAS[kind].sections)for(const f of s.fields)if(f.type==='select')draft[f.key]=f.values[0];if(kind==='contract')draft.group=moduleName==='Contracts'?tabName:moduleName==='Workplace'?'Langganan':'Sewa';if(kind==='asset'){draft.group=moduleName==='Assets'?tabName:'Register';if(moduleName==='Fleet')draft.assetClass='Kendaraan'}if(kind==='bill')Object.assign(draft,{status:'DRAFT',source:role,review:'Belum diperiksa',lines:[{description:'',amount:'',site:draft.site,account:'',ref:'',prepaid:false}],tax:0,discount:0,withholding:0});if(kind==='vendor')draft.bankStatus='UNVERIFIED';Object.assign(draft,defaults);isNew=true;detailTab='Form';$('chooser').close();showEditor()}
function showEditor(){let schema=SCHEMAS[draft.kind];$('record-type').textContent=`${schema.label} · ${draft.id} · ${draft.status}`;$('record-title').textContent=draft.name||`Buat ${schema.label.toLowerCase()}`;$('detail-tabs').innerHTML=['Form','Dokumen','Terhubung','Riwayat'].map(t=>`<button type="button" data-detail-tab="${t}" class="${detailTab===t?'active':''}">${t}${t==='Dokumen'?` (${draft.files.length})`:''}</button>`).join('');$('form-error').textContent='';
if(detailTab==='Form'){$('form-body').innerHTML=(locked()?'<div class="warning">'+(draft.kind==='bill'?'Bill sudah POSTED dan tidak dapat diedit. Koreksi melalui dokumen koreksi Finance (belum disimulasikan).':'Ganti peran ke Finance untuk mengelola template recurring.')+'</div>':'')+(draft.kind==='bill'?`<div class="flow"><span>01 · Draft / invoice masuk</span><span>02 · Review Finance</span><span>03 · Posting</span><span>04 · Bayar</span></div>${draft.expected?`<div class="readonly">Perkiraan ${money(draft.expected)} · ambang ${draft.tolerance}%<br>Invoice ditunggu: ${draft.expectedArrival} · <b>Nominal aktual harus dikonfirmasi.</b></div>`:''}`:'')+schema.sections.map(s=>`<section class="section"><h3>${s.title}</h3>${s.hint?`<p>${s.hint}</p>`:''}<div class="fields">${s.fields.filter(visibleField).map(fieldHTML).join('')}</div></section>`).join('')+(draft.kind==='bill'?billLinesHTML():'')+(draft.kind==='template'?`<div class="readonly">Aksi generate akan membuat satu draft untuk periode ${escapeHTML(draft.next||'belum diisi')}. Menjalankannya lagi pada periode sama membuka draft yang sudah ada. Untuk periode selanjutnya, ubah tanggal awal periode.</div>`:'');}
if(detailTab==='Dokumen')$('form-body').innerHTML=`<h3>Lampiran pada ${draft.id}</h3><p>PDF / gambar disimpan lokal di browser. Maksimal 500 KB per file, total sekitar 2 MB. Tidak diunggah ke server.</p>${draft.files.map((f,i)=>`<div class="related"><div>${escapeHTML(f.name)}<br><small>${f.sample?'Bukti dummy demo; bukan file invoice asli':`${Math.round(f.size/1024)} KB · ${escapeHTML(f.type)}`}</small></div><div>${f.data?`<button type="button" data-download="${i}">Unduh</button>`:''}${!locked()?` <button type="button" data-remove-file="${i}">Lepas</button>`:''}</div></div>`).join('')||'<p>Belum ada lampiran.</p>'}${!locked()?'<input class="file-input" id="attachment" type="file" accept="application/pdf,image/png,image/jpeg" multiple aria-label="Tambah lampiran">':''}`;
if(detailTab==='Terhubung')renderRelated();if(detailTab==='Riwayat')$('form-body').innerHTML=draft.history.length?draft.history.slice().reverse().map(a=>`<div class="audit"><b>${escapeHTML(a.action)}</b> · ${escapeHTML(a.actor)}<p>${escapeHTML(a.at)}<br>${escapeHTML(a.changes)}</p></div>`).join(''):'<p>Belum ada perubahan setelah seed contoh.</p>';
let buttons='<button type="button" data-action="close">Tutup</button>';if(!locked())buttons+='<button type="submit" class="primary">Simpan</button>';if(!isNew){if(draft.kind==='bill'){if(['DRAFT','RETURNED','WAITING_INVOICE'].includes(draft.status))buttons+='<button type="button" data-action="submit-bill" class="primary">Ajukan ke Finance</button>';if(role==='Finance'&&draft.status==='SUBMITTED')buttons+='<button type="button" data-action="return-bill">Kembalikan</button><button type="button" data-action="hold-bill">Tahan</button><button type="button" data-action="post-bill" class="primary">Posting simulasi</button>';if(role==='Finance'&&draft.status==='HOLD')buttons+='<button type="button" data-action="release-bill">Lanjutkan review</button>';}else if(['contract','repair','asset','fuel','supply','cleaning'].includes(draft.kind)&&!(draft.kind==='contract'&&draft.group==='Disewakan'))buttons+='<button type="button" data-action="new-invoice">Ajukan invoice ↗</button>';if(draft.kind==='template'&&role==='Finance')buttons+='<button type="button" data-action="generate" class="primary">Generate periode ini</button>';if(draft.kind==='task')buttons+='<button type="button" data-action="work">Buat pekerjaan</button>';if(draft.kind==='vendor'&&role==='Finance'&&draft.bankStatus!=='VERIFIED')buttons+='<button type="button" data-action="verify-bank">Verifikasi rekening demo</button>';}
$('form-actions').innerHTML=buttons;if(!$('editor').open)$('editor').showModal()}
function billLinesHTML(){const refs=db.filter(r=>['contract','repair','asset','fuel','supply','cleaning'].includes(r.kind)&&r.group!=='Disewakan');return `<section class="section"><h3>Baris invoice & alokasi biaya</h3><p>Setiap baris menunjuk satu sumber dan satu lokasi. Tidak menjumlahkan total invoice penuh ke setiap referensi.</p><div class="bill-lines"><table><thead><tr><th>Uraian</th><th>Nominal IDR</th><th>Lokasi</th><th>Referensi</th><th>Akun Finance</th><th>Prepaid</th><th></th></tr></thead><tbody>${draft.lines.map((l,i)=>`<tr><td><input class="desc" aria-label="Uraian baris ${i+1}" data-index="${i}" data-line-key="description" value="${escapeHTML(l.description)}" ${locked()?'disabled':''}></td><td><input type="number" min="0" aria-label="Nominal baris ${i+1}" data-index="${i}" data-line-key="amount" value="${l.amount}" ${locked()?'disabled':''}></td><td><select aria-label="Lokasi baris ${i+1}" data-index="${i}" data-line-key="site" ${locked()?'disabled':''}>${['HO','C007','C008'].map(s=>`<option ${s===l.site?'selected':''}>${s}</option>`).join('')}</select></td><td><select class="reference" aria-label="Referensi baris ${i+1}" data-index="${i}" data-line-key="ref" ${locked()?'disabled':''}><option value="">Tanpa referensi</option>${refs.map(r=>`<option value="${r.id}" ${r.id===l.ref?'selected':''}>${r.id} · ${escapeHTML(r.name)}</option>`).join('')}</select></td><td><input aria-label="Akun baris ${i+1}" data-index="${i}" data-line-key="account" value="${escapeHTML(l.account)}" ${locked()||role!=='Finance'?'disabled':''}></td><td><input type="checkbox" aria-label="Prepaid baris ${i+1}" data-index="${i}" data-line-key="prepaid" ${l.prepaid?'checked':''} ${locked()||role!=='Finance'?'disabled':''}></td><td>${!locked()?`<button type="button" data-remove-line="${i}" aria-label="Hapus baris ${i+1}">×</button>`:''}</td></tr>`).join('')}</tbody></table></div><div class="line-actions">${!locked()?'<button type="button" data-action="add-line">＋ Baris</button>':''}<b id="bill-total">Total invoice: ${money(Model.gross(draft))}</b></div></section>`}
function renderRelated(){let ids=new Set([draft.vendor,draft.asset,draft.contract,...(draft.lines||[]).map(l=>l.ref)].filter(Boolean));db.filter(r=>r.id!==draft.id&&(r.asset===draft.id||r.contract===draft.id||r.vendor===draft.id||r.schedule===draft.id||(r.lines||[]).some(l=>l.ref===draft.id))).forEach(r=>ids.add(r.id));let html='';if(['contract','repair','fuel','cleaning'].includes(draft.kind))html=`<div class="readonly">Biaya dialokasikan dari bill POSTED · hanya baca<br><strong>${money(Model.relatedAmount(db,draft.id))}</strong><br>Basis: subtotal baris terkait sebelum pajak dan diskon invoice. Bukan nilai kontrak, total utang, atau total pembayaran.</div>`;if(draft.kind==='repair'&&draft.estimate)html=`<div class="readonly">Estimasi biaya operasional GA: ${money(draft.estimate)} · bukan invoice dan tidak masuk total aktual.</div>`;if(draft.kind==='contract'&&draft.group==='Disewakan')html='<div class="warning">Disewakan menghasilkan invoice pelanggan / AR. Alur AR dicatat di peta use case; tidak dibuat sebagai supplier bill.</div>';if(draft.kind==='document'&&draft.contract)html+=`<div class="readonly">Berlaku sampai ${escapeHTML(byId(draft.contract)?.end||'Tidak ditetapkan')} · dibaca dari kontrak.</div>`;
html+=Array.from(ids).filter(id=>byId(id)).map(id=>{let r=byId(id);return `<div class="related"><button type="button" class="link" data-related="${id}">${escapeHTML(r.name)} · ${id}</button>${badge(r.status)}</div>`}).join('')||'<p>Tidak ada record lain yang terhubung.</p>';
if(draft.kind==='bill'){html+=`<div class="readonly">Subtotal: ${money(Model.subtotal(draft))}<br>Total invoice: ${money(Model.gross(draft))}<br>Potongan saat bayar: ${money(draft.withholding)}<br>Dibayar: ${money(Model.paid(draft))}<br>Sisa dibayar: ${money(Model.net(draft)-Model.paid(draft))}</div>`;if(draft.lines.some(l=>l.prepaid))html+=`<div class="readonly">Prepaid menggunakan periode bill ${escapeHTML(draft.start)} sampai ${escapeHTML(draft.end)}. Preview belum membuat jadwal/jurnal pengakuan beban.</div>`;if(role==='Finance'&&draft.status==='POSTED'&&Model.net(draft)>Model.paid(draft))html+=`<section class="section"><h3>Pembayaran simulasi</h3><p>Rekening vendor: ${escapeHTML(byId(draft.vendor)?.bankStatus||'UNVERIFIED')}. Tidak ada transaksi bank nyata.</p><div class="fields"><div class="field"><label for="pay-amount">Jumlah IDR</label><input id="pay-amount" type="number" min="1" value="${Model.net(draft)-Model.paid(draft)}"></div><div class="field"><label for="pay-date">Tanggal</label><input id="pay-date" type="date" value="${TODAY}"></div><div class="field wide"><label for="pay-bank">Rekening sumber perusahaan</label><input id="pay-bank" value="Bank perusahaan · DEMO"></div></div><p><button type="button" class="primary" data-action="pay">Catat pembayaran simulasi</button></p></section>`;html+=(draft.payments||[]).map(p=>`<p>${escapeHTML(p.date)} · ${money(p.amount)} · ${escapeHTML(p.bank)}</p>`).join('')}
$('form-body').innerHTML=html}
function save(action='Simpan perubahan'){capture();if(attachmentBusy)throw Error('Tunggu pembacaan lampiran selesai.');if(locked())throw Error('Record hanya baca untuk status/peran ini.');const errors=Model.validate(db,draft);if(errors.length)throw Error(errors.join(' '));let old=byId(draft.id);if(draft.kind==='vendor'&&old&&['bank','bankNumber','bankHolder'].some(k=>old[k]!==draft[k]))draft.bankStatus='UNVERIFIED';let changes=Object.keys(draft).filter(k=>!['history','files'].includes(k)&&JSON.stringify(old?.[k])!==JSON.stringify(draft[k])).map(k=>`${k}: ${typeof draft[k]==='object'?'diperbarui':String(old?.[k]??'—')+' → '+String(draft[k])}`).join('\n');if(JSON.stringify(old?.files)!==JSON.stringify(draft.files))changes+='\nLampiran diperbarui';Model.audit(draft,role,isNew?'Record dibuat':action,changes);if(old)db[db.indexOf(old)]=clone(draft);else db.push(clone(draft));isNew=false;const durable=persist();render();if(durable)toast('Tersimpan di browser ini');return draft}
function handleAction(action){try{
if(action==='close'){$('editor').close();draft=null;return}if(action==='close-chooser'){$('chooser').close();return}if(action==='finance'){go('Finance','Inbox');return}if(action==='create'){let kinds=allowedKinds();if(moduleName==='Finance'&&tabName==='Tagihan rutin'&&role!=='Finance'){toast('Pilih peran Finance untuk membuat template');return}if(kinds.length===1)create(kinds[0]);else{$('choices').innerHTML=kinds.map(k=>`<button class="choice" data-create-kind="${k}">${SCHEMAS[k].label}<small>Form lengkap · simpan ke register bersama</small></button>`).join('');$('chooser').showModal()}return}if(action==='coverage'){showCoverage();return}if(action==='export'){downloadBlob(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),'ga-demo.json');return}
if(action==='add-line'){capture();draft.lines.push({description:'',amount:'',site:draft.site,ref:'',account:'',prepaid:false});showEditor();return}
if(action==='new-invoice'){save();let ref=draft.id;create('bill',{name:`Invoice · ${draft.name}`,vendor:draft.vendor||byId(draft.contract)?.vendor||'',site:draft.site,lines:[{description:draft.name,amount:'',site:draft.site,ref,account:byId(draft.vendor)?.defaultAccount||'',prepaid:false}]});return}
if(['submit-bill','post-bill','return-bill','hold-bill','release-bill'].includes(action)){save();let current=byId(draft.id);Model.transition(db,current,action.split('-')[0],role);persist();draft=clone(current);showEditor();render();return}
if(action==='generate'){save();const result=Model.generate(db,byId(draft.id));persist();render();openRecord(result.id);return}
if(action==='work'){save();const occurrence=draft.next,existing=db.find(r=>r.kind==='repair'&&r.schedule===draft.id&&r.occurrence===occurrence);if(existing){openRecord(existing.id);return}const parent=clone(draft);create('repair',{name:parent.name,asset:parent.asset,vendor:parent.vendor||'',contract:parent.contract||'',site:parent.site,scheduled:parent.next,schedule:parent.id,occurrence,symptoms:parent.checklist,serviceType:'Servis berkala',failure:TODAY,status:'Dijadwalkan'});return}
if(action==='verify-bank'){save();if(role!=='Finance')throw Error('Verifikasi milik Finance.');let r=byId(draft.id);if(!r.bank||!r.bankNumber||!r.bankHolder)throw Error('Lengkapi nama bank, nomor rekening, dan nama pemilik dahulu.');r.bankStatus='VERIFIED';Model.audit(r,role,'Rekening diverifikasi · simulasi');persist();openRecord(r.id);return}
if(action==='pay'){const r=byId(draft.id);Model.pay(db,r,Number($('pay-amount').value),$('pay-date').value,$('pay-bank').value,role);persist();draft=clone(r);showEditor();render();return}
}catch(error){$('form-error').textContent=error.message}}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action)handleAction(b.dataset.action);if(b.dataset.menu)go(b.dataset.menu);if(b.dataset.tab)go(moduleName,b.dataset.tab);if(b.dataset.open)openRecord(b.dataset.open);if(b.dataset.createKind)create(b.dataset.createKind);if(b.dataset.detailTab){capture();detailTab=b.dataset.detailTab;showEditor()}if(b.dataset.related){openRecord(b.dataset.related)}if(b.dataset.removeLine!==undefined){capture();draft.lines.splice(Number(b.dataset.removeLine),1);showEditor()}if(b.dataset.removeFile!==undefined){draft.files.splice(Number(b.dataset.removeFile),1);showEditor()}if(b.dataset.download!==undefined){const f=draft.files[Number(b.dataset.download)];const a=document.createElement('a');a.href=f.data;a.download=f.name;a.click()}});
$('record-form').addEventListener('submit',e=>{e.preventDefault();try{save();showEditor()}catch(error){$('form-error').textContent=error.message}});
$('role').addEventListener('change',()=>{role=$('role').value;render()});$('search').addEventListener('input',renderRows);$('site-filter').addEventListener('change',renderRows);
document.addEventListener('input',e=>{if(draft?.kind==='bill'&&detailTab==='Form'&&(e.target.dataset.lineKey||['field-tax','field-discount'].includes(e.target.id))){capture();if($('bill-total'))$('bill-total').textContent='Total invoice: '+money(Model.gross(draft))}});
document.addEventListener('change',async e=>{if(['field-group','field-assetClass'].includes(e.target.id)){capture();showEditor();return}if(e.target.id!=='attachment')return;attachmentBusy=true;const target=draft;try{for(const file of e.target.files){if(!['application/pdf','image/png','image/jpeg'].includes(file.type))throw Error('Gunakan PDF, PNG, atau JPEG.');if(file.size>500000)throw Error('File terlalu besar; maksimal 500 KB.');if(db.flatMap(r=>r.files).reduce((n,f)=>n+(f.size||0),0)+target.files.reduce((n,f)=>n+(f.size||0),0)+file.size>2000000)throw Error('Batas lampiran demo 2 MB tercapai.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});target.files.push({name:file.name,type:file.type,size:file.size,data})}if(draft===target)showEditor()}catch(err){$('form-error').textContent=err.message}finally{attachmentBusy=false}});
function showCoverage(){ $('choices').innerHTML=`<div class="coverage-card"><h3>Audit cakupan GA → Finance</h3><p>“Interaktif” berarti jalur inti dapat dicoba. “Rancangan” adalah keputusan/alur yang perlu implementasi berikutnya, bukan fitur backend yang sudah tersedia.</p><a href="GA-USE-CASES.md" target="_blank">Buka analisis lengkap & temuan kode ↗</a></div>`+USE_CASES.map(c=>`<div class="coverage-card">${badge(c[3])}<b>${c[0]} · ${c[1]}</b><p>${c[2]}</p></div>`).join('');$('chooser').showModal()}
render();
